<?php
/**
 * Object cache drop-in detection, backend health and micro-benchmark.
 *
 * @package cosmic-cache
 */

declare( strict_types=1 );

namespace CosmicCache\ObjectCache;

final class Status {

	/**
	 * Does wp-content/object-cache.php exist?
	 *
	 * @return bool
	 */
	public static function dropin_exists(): bool {
		return is_file( WP_CONTENT_DIR . '/object-cache.php' );
	}

	/**
	 * Is the current object-cache drop-in generated by Cosmic Cache?
	 *
	 * Checks the machine marker (/* COSMIC_CACHE_GENERATED *\/) rather than a
	 * loose "Cosmic Cache" string, so a foreign drop-in that merely mentions
	 * the plugin is never mistaken for ours.
	 *
	 * @return bool
	 */
	public static function dropin_is_cosmic(): bool {
		$file = WP_CONTENT_DIR . '/object-cache.php';
		if ( ! is_file( $file ) ) {
			return false;
		}
		$contents = (string) file_get_contents( $file );
		return false !== strpos( $contents, 'COSMIC_CACHE_GENERATED' );
	}

	/**
	 * Detect the backend of the currently active object-cache drop-in.
	 *
	 * @return array{type:string,version:string}
	 */
	public static function active_backend(): array {
		$file = WP_CONTENT_DIR . '/object-cache.php';
		if ( ! is_file( $file ) ) {
			return array( 'type' => 'none', 'version' => '' );
		}

		$contents = strtolower( (string) file_get_contents( $file ) );

		if ( false !== strpos( $contents, 'redis' ) ) {
			return array( 'type' => 'redis', 'version' => self::redis_version() );
		}
		if ( false !== strpos( $contents, 'memcached' ) || false !== strpos( $contents, 'memcache' ) ) {
			return array( 'type' => 'memcached', 'version' => '' );
		}
		if ( false !== strpos( $contents, 'apcu' ) ) {
			return array( 'type' => 'apcu', 'version' => phpversion( 'apcu' ) ?: '' );
		}

		return array( 'type' => 'unknown', 'version' => '' );
	}

	/**
	 * Available backend extensions.
	 *
	 * @return array<int,string>
	 */
	public static function available_backends(): array {
		$backends = array();
		if ( class_exists( 'Redis' ) ) {
			$backends[] = 'redis';
		}
		if ( function_exists( 'apcu_fetch' ) ) {
			$backends[] = 'apcu';
		}
		return $backends;
	}

	/**
	 * Redis server version via phpredis info().
	 *
	 * @return string
	 */
	private static function redis_version(): string {
		if ( ! class_exists( 'Redis' ) ) {
			return '';
		}
		try {
			$redis = new \Redis();
			$redis->connect( '127.0.0.1', 6379, 1 );
			$info = $redis->info( 'server' );
			return isset( $info['redis_version'] ) ? (string) $info['redis_version'] : '';
		} catch ( \Exception $e ) {
			return '';
		}
	}

	/**
	 * Micro-benchmark of the active drop-in (get/set round trips).
	 *
	 * @param int $ops
	 * @return array{success:bool,ops:int,elapsed_ms:float,ops_per_sec:float}
	 */
	public static function benchmark( int $ops = 100 ): array {
		$start  = microtime( true );
		$success = true;

		for ( $i = 0; $i < $ops; $i++ ) {
			$key = 'cosmic_bench_' . $i;
			wp_cache_set( $key, $i, 'cosmic_bench' );
			if ( wp_cache_get( $key, 'cosmic_bench' ) !== $i ) {
				$success = false;
			}
		}

		$elapsed = ( microtime( true ) - $start ) * 1000;
		wp_cache_flush_runtime();

		return array(
			'success'    => $success,
			'ops'        => $ops,
			'elapsed_ms' => round( $elapsed, 2 ),
			'ops_per_sec' => round( $ops / max( 0.001, $elapsed / 1000 ), 0 ),
		);
	}
}
